alter table public.profiles enable row level security;

drop policy if exists "Users can view own profile" on public.profiles;
create policy "Users can view own profile" on public.profiles
  for select to authenticated using (auth.uid() = user_id);

drop policy if exists "Admins can view org profiles" on public.profiles;
create policy "Admins can view org profiles" on public.profiles
  for select to authenticated using (public.has_role(auth.uid(), 'admin'));

grant select on public.profiles to authenticated;

-- Backfill existing users
insert into public.profiles (user_id, display_name, referral_code)
select u.id,
       coalesce(u.raw_user_meta_data->>'display_name', split_part(u.email, '@', 1)),
       substr(md5(random()::text || u.id::text), 1, 8)
from auth.users u
on conflict (user_id) do nothing;

-- New sign-ups get a profile (never blocks sign-up if something goes wrong)
create or replace function public.handle_new_user_profile()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (user_id, display_name, referral_code)
  values (new.id,
          coalesce(new.raw_user_meta_data->>'display_name', split_part(new.email, '@', 1)),
          substr(md5(random()::text || new.id::text), 1, 8))
  on conflict (user_id) do nothing;
  return new;
exception when others then
  return new;
end; $$;

